 ]},
 {"clause_id": "c028", "issues": [
   {"issue": "Clause (vii) is joined to clause (vi) by \"or\" but has no subject or operative verb — \"with respect to any other matter which in the judgment of the Depositor will be determined adversely\" — so what is being represented cannot be read off the words. The broken sentence changes the content of the no-litigation representation.", "type": 1, "prob": 0.36},
   {"issue": null, "type": 2, "prob": 0.07}
 ]},
 {"clause_id": "c029", "issues": [
